import { iconMarkup } from "./icons.js";
import "./i18n.js";
import { KEYS, read, write, id, todayISO, escapeHtml, formatDate, percent, getSettings, saveSettings, allData, clearAll, importData, replaceDataFromServer, sanitizeNoteHtml } from "./storage.js";
import { renderDashboard, drawDashboardCharts } from "./dashboard.js";
import { renderSubjects } from "./subjects.js";
import { renderScores, setScoreFilter, resetScoreFilters } from "./scores.js";
import { renderPlanner, setPlannerFilter, movePlannerMonth, selectPlannerDate, goToPlannerToday, setPlannerView, loadPlannerClassEvents, setPlannerClassEvents } from "./planner.js";
import { renderTimer, startTimer, pauseTimer, resetTimer, setTimerMode, saveDurations, resumeTimerIfNeeded } from "./timer.js";
import { renderGoals } from "./goals.js";
import { renderNotes, setNoteSearch } from "./notes.js";
import { renderAnalytics, drawAnalyticsCharts, setAnalyticsFilter } from "./analytics.js";
import { renderAchievements, syncAchievements } from "./achievements.js";
import { authActive, currentUser, restoreSession, authenticate, requestPasswordReset, resetPassword, logout, clearSession, getRemoteData, uploadData, updateAccount, deleteRemoteData, createClass, joinClass, createAssignment, submitAssignment, gradeSubmission, classMessages, sendClassMessage, studentProfile, createQuiz, getQuiz, submitQuiz, quizAttempts, peopleLookup, directMessages, sendDirectMessage, adminOverview, manageAccount, linkedOAuthProviders, startOAuthLink, getAppSettings, updateAdminSettings } from "./auth.js";
import { renderClassroom, renderChatMessages, selectedClass, selectClass, selectChatContact, stopClassChat } from "./classroom.js";
