import { renderAdminShell, renderAdminOverview } from "./admin.js";

const view=document.getElementById("page-view"),modalRoot=document.getElementById("modal-root"),sidebar=document.getElementById("sidebar"),authRoot=document.getElementById("auth-root"),appShell=document.getElementById("app-shell");
let currentPage="dashboard",lastPage="dashboard",submissionFiles=[],directPeer=null,directPollTimer=null,adminSearch="",adminData=null,adminBackground="angkor",arrivalWelcomeTimer=null;
const titles={dashboard:"Dashboard",subjects:"Subjects",scores:"Score tracker",planner:"Study planner",timer:"Pomodoro timer",goals:"Study goals",notes:"Personal notes",analytics:"Analytics",achievements:"Achievements",classroom:"Classroom",messages:"Messages",admin:"Admin console",settings:"Settings & privacy"};
const renderers={dashboard:renderDashboard,subjects:renderSubjects,scores:renderScores,planner:renderPlanner,timer:renderTimer,goals:renderGoals,notes:renderNotes,analytics:renderAnalytics,achievements:renderAchievements,classroom:()=>"",messages:renderMessages,admin:renderAdminShell,settings:renderSettings};

function navigate(page){if(!renderers[page]||(page==="admin"&&currentUser()?.role!=="admin"))return;if(page!=="classroom")stopClassChat();if(page!=="messages")stopDirectMessages();currentPage=page;if(page!=="settings")lastPage=page;sidebar.classList.remove("open");document.querySelectorAll(".nav-item[data-page]").forEach(button=>button.classList.toggle("active",button.dataset.page===page));document.getElementById("breadcrumb-page").textContent=titles[page];if(page==="classroom")renderClassroom(view,currentUser(),()=>currentPage==="classroom");else view.innerHTML=renderers[page]();view.focus({preventScroll:true});window.scrollTo({top:0,behavior:"smooth"});if(page==="dashboard")requestAnimationFrame(drawDashboardCharts);if(page==="analytics")requestAnimationFrame(drawAnalyticsCharts);if(page==="timer")resumeTimerIfNeeded();if(page==="messages")loadDirectInbox();if(page==="admin")loadAdminConsole();if(page==="settings")loadOAuthConnections();if(page==="planner")loadPlannerClassEvents().then(events=>{setPlannerClassEvents(events);if(currentPage==="planner")view.innerHTML=renderPlanner();});}
function refresh(){navigate(currentPage);syncProfileChrome();}
function notify(message,type="success"){const region=document.getElementById("toast-region"),toast=document.createElement("div");toast.className=`toast ${type}`;toast.textContent=message;region.append(toast);setTimeout(()=>toast.remove(),3200);}
async function loadOAuthConnections(){const root=document.getElementById("oauth-provider-list");if(!root)return;try{const{providers=[]}=await linkedOAuthProviders(),connected=new Set(providers);root.innerHTML=[["google","Google"],["github","GitHub"],["telegram","Telegram"]].map(([id,label])=>`<div class="oauth-provider-row"><span><b>${label}</b><small>${connected.has(id)?"Connected to this account":"Not connected"}</small></span>${connected.has(id)?`<span class="oauth-connected"><i></i> Connected</span>`:`<button type="button" class="btn btn-small btn-soft" data-action="link-oauth-provider" data-provider="${id}">Connect</button>`}</div>`).join("");}catch(error){root.innerHTML=`<span class="help-text">${escapeHtml(error.message||"Could not load connected sign-in methods.")}</span>`;}}
async function linkOAuthProvider(button){const provider=button.dataset.provider;if(!provider)return;button.disabled=true;try{const{url}=await startOAuthLink(provider);if(!url)throw new Error("The provider did not return a sign-in link.");window.location.assign(url);}catch(error){notify(error.message||"Could not connect that sign-in method.","error");button.disabled=false;}}
window.addEventListener("studytrack:toast",event=>notify(event.detail?.message||"Updated",event.detail?.type||"success"));
window.addEventListener("studytrack:refresh",refresh);
function stopDirectMessages(){if(directPollTimer){clearInterval(directPollTimer);directPollTimer=null;}}
async function withSharedProfilePhoto(person){if(!person?.id)return person;try{const{profile}=await studentProfile(person.id);return{...person,avatar:profile?.avatar||person.avatar||"",photo:safePhoto(profile?.photo)};}catch{return{...person,photo:""};}}
async function loadDirectInbox(){const list=document.getElementById("direct-thread-list"),panel=document.getElementById("direct-conversation-panel");if(!list||!panel)return;try{const{threads=[]}=await directMessages();if(!directPeer){list.innerHTML=renderDirectThreads(threads);return;}const data=await directMessages(directPeer.id);directPeer=await withSharedProfilePhoto(data.peer);list.innerHTML=renderDirectThreads(threads,directPeer.id,directPeer);panel.innerHTML=renderDirectConversation(directPeer,data.messages||[],currentUser()?.id||"");const feed=panel.querySelector("#direct-message-feed");if(feed)feed.scrollTop=feed.scrollHeight;startDirectPolling();}catch(error){list.innerHTML=`<div class="direct-thread-empty"><b>Could not load conversations</b><small>${escapeHtml(error.message||"Try refreshing the page.")}</small></div>`;}}
async function searchPeople(email){const result=document.getElementById("people-search-result");if(!result)return;result.innerHTML=`<div class="people-search-message">Looking for that account…</div>`;try{const{person}=await peopleLookup(email);result.innerHTML=renderPersonSearch(person?await withSharedProfilePhoto(person):null);}catch(error){result.innerHTML=`<div class="people-search-message error">${escapeHtml(error.message||"Could not search for that account.")}</div>`;}}
async function openDirectConversation(peerId){if(!peerId)return;try{stopDirectMessages();const data=await directMessages(peerId),peer=await withSharedProfilePhoto(data.peer);directPeer=peer;const list=document.getElementById("direct-thread-list"),panel=document.getElementById("direct-conversation-panel");if(!panel)return;panel.innerHTML=renderDirectConversation(peer,data.messages||[],currentUser()?.id||"");const feed=panel.querySelector("#direct-message-feed");if(feed)feed.scrollTop=feed.scrollHeight;if(list){try{const{threads=[]}=await directMessages();list.innerHTML=renderDirectThreads(threads,peerId,peer);}catch{}}startDirectPolling();}catch(error){notify(error.message||"Could not open that conversation","error");}}
function startDirectPolling(){stopDirectMessages();if(currentPage!=="messages"||!directPeer)return;let busy=false;directPollTimer=setInterval(async()=>{if(currentPage!=="messages"||!directPeer){stopDirectMessages();return;}if(busy)return;busy=true;try{const peerId=directPeer.id,[conversation,inbox]=await Promise.all([directMessages(peerId),directMessages()]);directPeer={...conversation.peer,avatar:directPeer.avatar||"",photo:directPeer.photo||""};const list=document.getElementById("direct-thread-list"),feed=document.getElementById("direct-message-feed");if(list)list.innerHTML=renderDirectThreads(inbox.threads||[],peerId,directPeer);if(feed){const nearBottom=feed.scrollHeight-feed.scrollTop-feed.clientHeight<56;feed.innerHTML=renderDirectMessageFeed(conversation.messages||[],currentUser()?.id||"");if(nearBottom)feed.scrollTop=feed.scrollHeight;}}catch{}finally{busy=false;}},6500);}
async function handleDirectChatSubmit(form){const body=String(new FormData(form).get("body")||"").trim(),peerId=form.dataset.peerId,file=form.querySelector("#direct-chat-file")?.files?.[0]||null,button=form.querySelector("button[type=submit]");if(!body&&!file)return;if(file&&file.size>8*1024*1024){notify("Chat files must be no larger than 8 MB","error");return;}if(button){button.disabled=true;button.classList.add("is-loading");}try{const attachment=file?await encodeSubmissionFile(file):null;await sendDirectMessage(peerId,body,attachment);form.reset();const picker=form.querySelector("#direct-chat-emoji-picker");if(picker)picker.hidden=true;renderDirectAttachmentPreview(form.querySelector("#direct-chat-file"));await openDirectConversation(peerId);}catch(error){notify(error.message||"Message could not be sent","error");}finally{if(button){button.disabled=false;button.classList.remove("is-loading");}}}
function renderDirectAttachmentPreview(input){const preview=document.getElementById("direct-chat-attachment-preview");if(!preview)return;const file=input?.files?.[0];if(!file){preview.innerHTML="";return;}if(file.size>8*1024*1024){if(input)input.value="";preview.innerHTML="";notify("Chat files must be no larger than 8 MB","error");return;}const size=file.size<1024?`${file.size} B`:file.size<1048576?`${(file.size/1024).toFixed(1)} KB`:`${(file.size/1048576).toFixed(1)} MB`;preview.innerHTML=`<span class="direct-selected-icon">${file.type.startsWith("image/")?"▧":"▤"}</span><span class="direct-selected-name" title="${escapeHtml(file.name)}">${escapeHtml(file.name)}</span><small>${size}</small><button type="button" data-action="remove-chat-attachment" aria-label="Remove attachment">×</button>`;}
function toggleChatEmojiPicker(button){const form=button.closest("#direct-chat-form"),picker=form?.querySelector("#direct-chat-emoji-picker");if(picker)picker.hidden=!picker.hidden;}
function insertChatEmoji(button){const form=button.closest("#direct-chat-form"),textarea=form?.querySelector("textarea[name=body]");if(!textarea)return;const start=textarea.selectionStart??textarea.value.length,end=textarea.selectionEnd??start;textarea.setRangeText(button.dataset.emoji||"",start,end,"end");textarea.focus();const picker=form.querySelector("#direct-chat-emoji-picker");if(picker)picker.hidden=true;}
async function loadAdminConsole(){const content=document.getElementById("admin-content");if(!content)return;try{const [overview,appearance]=await Promise.all([adminOverview(),getAppSettings().catch(()=>({background:"angkor"}))]);adminData=overview;adminBackground=appearance.background||"angkor";applyAdminBackground(adminBackground);content.innerHTML=renderAdminOverview(adminData,adminSearch,adminBackground);}catch(error){content.innerHTML=`<section class="panel admin-error-panel"><b>Admin view unavailable</b><p>${escapeHtml(error.message||"Check that you are signed in as an admin.")}</p><button class="btn btn-small btn-soft" data-action="refresh-admin">Try again</button></section>`;}}
async function toggleManagedAccount(button){const active=button.dataset.active==="true",userId=button.dataset.id;if(!window.confirm(`${active?"Restore":"Pause"} this account? ${active?"The user can sign in again after the next login.":"This immediately ends active sessions and blocks new sign-ins."}`))return;button.disabled=true;try{await manageAccount(userId,{active});notify(`Account ${active?"restored":"paused"}`);await loadAdminConsole();}catch(error){notify(error.message||"Could not update this account","error");button.disabled=false;}}
async function saveManagedRole(userId){const select=document.getElementById(`admin-role-${userId}`);if(!select)return;try{await manageAccount(userId,{role:select.value});notify("Account role updated");await loadAdminConsole();}catch(error){notify(error.message||"Could not update this role","error");}}
function syncProfileChrome(){const p=read("profile"),user=currentUser(),name=p.name||user?.name||"Student",initial=(p.avatar||name.charAt(0)||"S").slice(0,2).toUpperCase(),photo=safePhoto(p.photo);document.getElementById("sidebar-name").textContent=name;document.querySelector(".profile-meta small").textContent=`${user?.role?.[0]?.toUpperCase()||"S"}${user?.role?.slice(1)||"tudent"} account`;document.getElementById("admin-nav")?.classList.toggle("hidden",user?.role!=="admin");for(const el of [document.getElementById("sidebar-avatar"),document.getElementById("top-avatar")]){el.innerHTML=photo?`<img src="${escapeHtml(photo)}" alt="">`:escapeHtml(initial);el.classList.toggle("has-photo",Boolean(photo));}}
function safePhoto(value){return typeof value==="string"&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value)?value:"";}
function syncTheme(){const light=getSettings().theme==="light";document.body.classList.toggle("light-theme",light);const themeMeta=document.querySelector('meta[name="theme-color"]');if(themeMeta)themeMeta.content=light?"#f4f7ff":"#0b1120";const button=document.getElementById("theme-toggle");if(button){button.setAttribute("aria-label",`Switch to ${light?"dark":"light"} theme`);button.innerHTML=light?`<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/></svg>`:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 15.2A8.5 8.5 0 0 1 8.8 3.5 8.5 8.5 0 1 0 20.5 15.2Z"/></svg>`;}}
function migrateDarkThemeDefault(scope){const key=`studytrack_dark_default_v1:${scope}`;if(localStorage.getItem(key)==="1")return;const settings=getSettings();if(settings.theme==="light"){settings.theme="dark";saveSettings(settings);}localStorage.setItem(key,"1");}
function renderSettings(){const profile=read("profile"),settings=getSettings(),lock=settings.pinEnabled,user=currentUser(),photo=safePhoto(profile.photo),cover=safePhoto(profile.coverPhoto),initial=escapeHtml((profile.avatar||profile.name?.[0]||"S").slice(0,2).toUpperCase()),visibility=profile.visibility||"classmates";return `<div class="page-heading"><div><div class="eyebrow">MAKE STUDYTRACK YOURS</div><h1>Settings & privacy</h1><p>Manage your profile, account, and study workspace preferences.</p></div></div>
  <div class="settings-layout"><nav class="settings-nav panel" aria-label="Settings sections"><button class="active" data-settings-tab="profile">Profile</button><button data-settings-tab="preferences">Preferences</button><button data-settings-tab="privacy">Privacy center</button><button data-settings-tab="about">About</button></nav><div>
    <section class="settings-card panel" id="settings-profile"><h2>Personal profile</h2><p>Your name and profile pictures appear to classmates when you allow it.</p><div class="profile-cover-editor facebook-profile-editor"><div class="profile-cover-preview facebook-profile-cover" id="profile-cover-preview">${cover?`<img src="${escapeHtml(cover)}" alt="Profile cover photo">`:""}<span>${iconMarkup("image")} ${cover?"COVER PHOTO":"ADD A COVER PHOTO"}</span></div><div class="facebook-profile-bar"><div class="profile-photo-preview ${photo?"has-photo":""}" id="profile-photo-preview">${photo?`<img src="${escapeHtml(photo)}" alt="Profile picture">`:initial}</div><div class="facebook-profile-meta"><b>${escapeHtml(profile.name||user?.name||"Student")}</b><small>${user?.role==="teacher"?"Teacher":user?.role==="admin"?"Admin":"Student"} · StudyTrack profile</small></div><div class="profile-photo-actions"><label class="btn btn-small btn-soft" for="profile-photo-input">${iconMarkup("camera")} Upload picture</label><input id="profile-photo-input" class="hidden" type="file" accept="image/png,image/jpeg,image/webp">${photo?`<button class="text-action delete" data-action="remove-profile-photo">Remove photo</button>`:""}</div></div><div class="profile-cover-actions"><label class="btn btn-small btn-soft" for="profile-cover-input">${iconMarkup("image")} ${cover?"Change cover":"Upload cover photo"}</label><input id="profile-cover-input" class="hidden" type="file" accept="image/png,image/jpeg,image/webp">${cover?`<button class="text-action delete" data-action="remove-profile-cover">Remove cover</button>`:""}<small>Wide JPG, PNG, or WebP images work best. The image is resized before it is saved.</small></div></div><form id="profile-form"><div class="form-grid"><div class="form-group"><label for="profile-name">Display name</label><input class="field" id="profile-name" name="name" maxlength="60" required value="${escapeHtml(profile.name||user?.name||"")}"></div><div class="form-group"><label for="profile-avatar">Avatar initials</label><input class="field" id="profile-avatar" name="avatar" maxlength="2" value="${escapeHtml(profile.avatar||"")}" placeholder="Used when no picture is set"></div><div class="form-group full"><label for="profile-bio">About me</label><textarea id="profile-bio" name="bio" maxlength="280" placeholder="Share a little about what you are learning…">${escapeHtml(profile.bio||"")}</textarea><span class="help-text">Up to 280 characters. Keep personal contact information private.</span></div><div class="form-group full"><label for="profile-visibility">Who can see your photos and About me?</label><select class="select-field" id="profile-visibility" name="visibility"><option value="classmates" ${visibility==="classmates"?"selected":""}>People in my classes</option><option value="everyone" ${visibility==="everyone"?"selected":""}>Anyone with a StudyTrack account</option><option value="private" ${visibility==="private"?"selected":""}>Keep photos and About me private</option></select><span class="help-text">Anyone with an account can view your name, photo, cover, and bio when you choose that option. Your email, scores, notes, and study records stay private.</span></div></div><div style="margin-top:13px"><button class="btn btn-primary btn-small">Save profile</button></div></form><section class="oauth-settings-card"><h3>Connected sign-in methods</h3><p>Connect Google, GitHub, or Telegram to sign in to this same account next time.</p><div id="oauth-provider-list" class="oauth-provider-list"><span class="help-text">Loading sign-in methods…</span></div></section><div class="account-summary"><span class="account-role ${user?.role||"student"}">${user?.role==="teacher"?"Teacher":user?.role==="admin"?"Admin":"Student"} account</span><span>${escapeHtml(user?.email||"")}</span><button class="text-action delete" data-action="logout">Sign out</button></div></section>
    <section class="settings-card panel" id="settings-preferences"><h2>Workspace preferences</h2><p>Choose an easy-on-the-eyes theme and your default focus intervals.</p><div class="settings-row"><div><b>Color theme</b><small>Choose a bright light workspace or a quiet dark workspace.</small></div><select class="select-field" id="settings-theme"><option value="light" ${settings.theme==="light"?"selected":""}>Light</option><option value="dark" ${settings.theme==="dark"?"selected":""}>Dark</option></select></div><div class="form-grid" style="margin-top:14px"><div class="form-group"><label for="settings-focus">Focus · minutes</label><input class="field" type="number" id="settings-focus" min="1" max="180" value="${settings.focusMinutes}"></div><div class="form-group"><label for="settings-short">Short break · minutes</label><input class="field" type="number" id="settings-short" min="1" max="60" value="${settings.shortBreakMinutes}"></div><div class="form-group"><label for="settings-long">Long break · minutes</label><input class="field" type="number" id="settings-long" min="1" max="90" value="${settings.longBreakMinutes}"></div></div><div class="settings-actions"><button class="btn btn-soft btn-small" data-action="save-settings-preferences">Save preferences</button></div></section>
    <section class="settings-card panel" id="settings-privacy"><h2>Privacy center</h2><p>Your account lets you sign in and sync across devices.</p><div class="settings-row"><div><b>Account storage</b><small>Study records sync through the StudyTrack server. LocalStorage keeps a browser copy on this device. Profile pictures, cover photos, and About me text are saved with your account; the sharing setting controls what class members can view.</small></div><span class="local-indicator"><i></i> Account</span></div><div class="settings-actions"><button class="btn btn-small" data-action="export-data">↓ Export JSON backup</button><label class="btn btn-small" for="import-file">↑ Import backup</label><input id="import-file" class="hidden" type="file" accept="application/json,.json"></div><div class="settings-row" style="margin-top:12px"><div><b>Optional local PIN</b><small>Adds a casual browser lock. It does not encrypt your account data.</small></div><div style="display:flex;gap:7px">${lock?`<button class="btn btn-small" data-action="lock-now">Lock now</button>`:""}<button class="btn btn-small ${lock?"btn-soft":""}" data-action="${lock?"disable-pin":"enable-pin"}">${lock?"Disable PIN":"Set a PIN"}</button></div></div><div class="privacy-warning"><b>Security note:</b> Account data lives in the server's SQLite database. Passwords are stored as hashes; study records are not encrypted by this app, and the server owner can access its database. Use HTTPS when deployed online. The optional PIN is not an encryption layer.</div><div class="settings-actions"><button class="btn btn-danger btn-small" data-action="clear-data">Delete all study data from this account</button></div></section>
    <section class="settings-card panel" id="settings-about"><h2>About StudyTrack</h2><p>A study companion for students and teachers.</p><div class="about-feature-grid"><article><span>01</span><b>For students</b><small>Track scores, plan study time, share assignment files, and privately message teachers or classmates.</small></article><article><span>02</span><b>For teachers</b><small>Create classes, post assignments, review files, give feedback, and privately message students.</small></article><article><span>03</span><b>Across your devices</b><small>Sign in to access your private study workspace from devices that can reach the deployed server.</small></article></div><div class="privacy-warning">Teacher accounts need an access code provided by the app owner. Class work stays available only to class members and the teacher; profile pages share only the selected name, photos, and short bio.</div></section>
  </div></div>`;}

document.addEventListener("click",event=>{
  const noteCommand=event.target.closest("[data-note-command]");if(noteCommand){event.preventDefault();const editor=document.getElementById("note-document-editor");if(!editor)return;editor.focus();const command=noteCommand.dataset.noteCommand;document.execCommand(command,false,noteCommand.dataset.value||null);updateNoteWordCount();return;}
  const nav=event.target.closest("[data-page]");if(nav){navigate(nav.dataset.page);return;}
  const tab=event.target.closest("[data-settings-tab]");if(tab){document.querySelectorAll("[data-settings-tab]").forEach(x=>x.classList.toggle("active",x===tab));document.getElementById(`settings-${tab.dataset.settingsTab}`)?.scrollIntoView({behavior:"smooth",block:"start"});return;}
  const actionElement=event.target.closest("[data-action]");if(!actionElement)return;const action=actionElement.dataset.action,idValue=actionElement.dataset.id;
  switch(action){
    case "open-settings":navigate("settings");break;
    case "link-oauth-provider":linkOAuthProvider(actionElement);break;
    case "create-class":openClassForm();break;
    case "join-class":openJoinClassForm();break;
    case "open-class":selectClass(idValue);navigate("classroom");break;
    case "classroom-back":selectClass("");navigate("classroom");break;
    case "refresh-classroom":navigate("classroom");break;
    case "copy-class-code":copyClassCode(actionElement.dataset.code,actionElement);break;
    case "set-admin-background":saveAdminBackground(actionElement.dataset.background);break;
    case "select-chat-contact":selectChatContact(idValue);renderClassroom(view,currentUser(),()=>currentPage==="classroom");break;
    case "remove-submission-file":removeSubmissionFile(Number(actionElement.dataset.index));break;
    case "choose-chat-file":document.getElementById("direct-chat-file")?.click();break;
    case "remove-chat-attachment":{const input=document.getElementById("direct-chat-file");if(input)input.value="";renderDirectAttachmentPreview(input);break;}
    case "toggle-chat-emoji":toggleChatEmojiPicker(actionElement);break;
    case "insert-chat-emoji":insertChatEmoji(actionElement);break;
    case "add-assignment":openAssignmentForm(selectedClass());break;
    case "create-quiz":openQuizForm(selectedClass());break;
    case "add-quiz-question":appendQuizQuestion();break;
    case "remove-quiz-question":removeQuizQuestion(actionElement);break;
    case "take-quiz":openQuizAttempt(idValue);break;
    case "quiz-results":openQuizResults(idValue);break;
    case "quiz-review":openStudentQuizReview(idValue);break;
    case "submit-assignment":openStudentSubmissionForm(actionElement.dataset.classId,idValue);break;
    case "grade-submission":openGradeSubmissionForm(actionElement.dataset.classId,idValue,actionElement.dataset.maximum,actionElement.dataset.score,actionElement.dataset.feedback||"");break;
    case "remove-profile-photo":removeProfilePhoto();break;
    case "remove-profile-cover":removeProfileCover();break;
    case "view-profile":openSharedProfile(idValue);break;
    case "message-profile":closeModal();if(actionElement.dataset.classId&&actionElement.dataset.classId!=="null"){selectClass(actionElement.dataset.classId);selectChatContact(idValue);navigate("classroom");}else{navigate("messages");openDirectConversation(idValue);}break;
    case "logout":signOut();break;
    case "about-modal":openModal("About StudyTrack",{kind:"info",fields:`<div class="form-group full"><p>StudyTrack helps students manage learning and lets teachers create classes, share assignments, review submissions, and privately message students.</p><p>Accounts sign in through the StudyTrack server. Student records sync to the account and are visible to a teacher only after the student joins that teacher's class.</p></div>`},"Close");break;
    case "add-subject":openSubjectForm();break;
    case "edit-subject":openSubjectForm(idValue);break;
    case "delete-subject":deleteSubject(idValue);break;
    case "add-score":openScoreForm(null,actionElement.dataset.subject||"");break;
    case "edit-score":openScoreForm(idValue);break;
    case "delete-score":deleteRecord("scores",idValue,"assessment");break;
    case "add-task":openTaskForm(null,actionElement.dataset.date||"");break;
    case "edit-task":openTaskForm(idValue);break;
    case "delete-task":deleteRecord("tasks",idValue,"task");break;
    case "toggle-task":toggleTask(idValue);break;
    case "planner-month":movePlannerMonth(Number(actionElement.dataset.delta));refresh();break;
    case "planner-select-date":selectPlannerDate(actionElement.dataset.date);refresh();break;
    case "planner-today":goToPlannerToday();refresh();break;
    case "planner-view":setPlannerView(actionElement.dataset.view);refresh();break;
    case "skip-welcome":dismissArrivalWelcome();break;
    case "planner-open-class":selectClass(actionElement.dataset.classId);navigate("classroom");break;
    case "add-goal":openGoalForm();break;
    case "edit-goal":openGoalForm(idValue);break;
    case "delete-goal":deleteRecord("goals",idValue,"goal");break;
    case "goal-progress":openProgressForm(idValue);break;
    case "add-note":openNoteForm();break;
    case "edit-note":openNoteForm(idValue);break;
    case "delete-note":deleteRecord("notes",idValue,"note");break;
    case "timer-mode":setTimerMode(actionElement.dataset.mode);refresh();break;
    case "start-timer":startTimer();refresh();break;
    case "pause-timer":pauseTimer();refresh();break;
    case "reset-timer":resetTimer();refresh();break;
    case "save-timer-durations":saveTimerDurations("focus-duration","short-duration","long-duration");break;
    case "export-data":exportBackup();break;
    case "clear-data":clearApplicationData();break;
    case "enable-pin":openPinSetup();break;
    case "disable-pin":disablePin();break;
    case "lock-now":renderLock();break;
    case "save-settings-preferences":savePreferences();break;
    case "clear-score-filters":resetScoreFilters();navigate("scores");break;
    case "theme-toggle":toggleTheme();break;
    case "open-direct-chat":case "start-direct-chat":openDirectConversation(idValue);break;
    case "refresh-direct-messages":loadDirectInbox();break;
    case "refresh-admin":loadAdminConsole();break;
    case "admin-toggle-account":toggleManagedAccount(actionElement);break;
    case "admin-save-role":saveManagedRole(idValue);break;
  }
});
document.addEventListener("keydown",event=>{if(event.key==="Escape"&&document.querySelector(".arrival-welcome-screen"))dismissArrivalWelcome();});

