window.addEventListener("resize",()=>{if(currentPage==="dashboard")drawDashboardCharts();if(currentPage==="analytics")drawAnalyticsCharts();});
document.addEventListener("change",event=>{
  const el=event.target;
  if(el.id==="score-subject-filter"){setScoreFilter("subject",el.value);navigate("scores");}
  if(el.id==="score-type-filter"){setScoreFilter("type",el.value);navigate("scores");}
  if(el.id==="score-from-filter"){setScoreFilter("from",el.value);navigate("scores");}
  if(el.id==="score-to-filter"){setScoreFilter("to",el.value);navigate("scores");}
  if(el.id==="task-filter"){setPlannerFilter(el.value);navigate("planner");}
  if(el.id==="analytics-period"){setAnalyticsFilter("period",el.value);navigate("analytics");}
  if(el.id==="analytics-subject"){setAnalyticsFilter("subject",el.value);navigate("analytics");}
  if(el.id==="settings-theme"){const s=getSettings();s.theme=el.value;saveSettings(s);syncTheme();}
  if(el.id==="admin-background-file"&&el.files?.[0])saveCustomAdminBackground(el.files[0]);
  if(el.id==="import-file"&&el.files?.[0])importBackup(el.files[0]);
  if(el.id==="profile-photo-input"&&el.files?.[0])saveProfilePhoto(el.files[0]);
  if(el.id==="profile-cover-input"&&el.files?.[0])saveProfileCover(el.files[0]);
  if(el.id==="direct-chat-file")renderDirectAttachmentPreview(el);
  if((el.id==="submission-files"||el.id==="submission-folder")&&el.files?.length){addSubmissionFiles([...el.files]);el.value="";}
});
document.addEventListener("dragover",event=>{if(event.target.closest("[data-submission-drop]"))event.preventDefault();});
document.addEventListener("drop",event=>{const zone=event.target.closest("[data-submission-drop]");if(!zone)return;event.preventDefault();addSubmissionFiles([...(event.dataTransfer?.files||[])]);});
document.addEventListener("input",event=>{
  if(event.target.id==="note-document-editor")updateNoteWordCount();
  if(event.target.id==="note-search"){const pos=event.target.selectionStart;setNoteSearch(event.target.value);const value=event.target.value;view.innerHTML=renderers.notes();const next=document.getElementById("note-search");next.focus();next.setSelectionRange(pos,pos);}
  if(event.target.id==="admin-user-search"){const pos=event.target.selectionStart;adminSearch=event.target.value;if(adminData){document.getElementById("admin-content").innerHTML=renderAdminOverview(adminData,adminSearch,adminBackground);const next=document.getElementById("admin-user-search");next.focus();next.setSelectionRange(pos,pos);}}
});
document.addEventListener("submit",async event=>{
  if(event.target.id==="class-chat-form"){event.preventDefault();await handleClassChatSubmit(event.target);return;}
  if(event.target.id==="people-search-form"){event.preventDefault();await searchPeople(String(new FormData(event.target).get("email")||""));return;}
  if(event.target.id==="direct-chat-form"){event.preventDefault();await handleDirectChatSubmit(event.target);return;}
  if(event.target.id==="profile-form"){event.preventDefault();const form=new FormData(event.target),name=String(form.get("name")||"").trim(),avatar=String(form.get("avatar")||"").trim().slice(0,2).toUpperCase(),bio=String(form.get("bio")||"").trim().slice(0,280),value=String(form.get("visibility")||"classmates"),visibility=["private","everyone"].includes(value)?value:"classmates";if(!name)return;try{await updateAccount(name);const profile=read("profile");write("profile",{...profile,name,avatar:avatar||name.slice(0,1).toUpperCase(),bio,visibility,role:currentUser()?.role||profile.role});syncProfileChrome();notify("Profile saved");navigate("settings");}catch(error){notify(error.message||"Could not save the profile","error");}return;}
  const kind=event.target.dataset.form;if(!kind)return;event.preventDefault();await handleModalSubmit(event.target,kind);
});

authRoot.addEventListener("click",event=>{
  const roleButton=event.target.closest("[data-auth-role]");if(roleButton){renderAuthScreen(authRoot.dataset.mode||"login",roleButton.dataset.authRole,"",authDraft());return;}
  const modeButton=event.target.closest("[data-auth-mode]");if(modeButton){const nextMode=modeButton.dataset.authMode;if(nextMode==="forgot"){renderPasswordRecovery("request",authDraft());return;}if(authRoot.dataset.mode==="reset")window.history.replaceState(null,"",window.location.pathname+window.location.search);renderAuthScreen(nextMode,authRoot.dataset.role||"student","",authDraft());return;}
  if(event.target.closest("[data-action=about-modal]")){openModal("About StudyTrack",{kind:"info",fields:`<div class="form-group full"><p>StudyTrack helps students manage scores, goals, notes, and study time. Teachers can create classes, post assignments, and review student submissions.</p><p>Each user has a separate account. A teacher can view student information only after that student joins one of the teacher's classes.</p></div>`},"Close");}
});
