function openModal(title,body,submitLabel="Save",wide=false){modalRoot.innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal ${wide?"wide":""} ${body.kind==="note"?"note-modal":""} ${body.kind?.includes("quiz")?"quiz-modal":""}" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><header class="modal-head"><h2>${escapeHtml(title)}</h2><button class="icon-btn" type="button" data-close-modal aria-label="Close">×</button></header><form data-form="${body.kind}" class="modal-body"><div class="form-grid">${body.fields}</div><div class="modal-actions"><button type="button" class="btn" data-close-modal>Cancel</button><button type="submit" class="btn btn-primary">${escapeHtml(submitLabel)}</button></div></form></section></div>`;modalRoot.querySelector("input:not([type=hidden]),textarea,select")?.focus();}
document.addEventListener("mousedown",event=>{if(event.target.closest("[data-note-command]"))event.preventDefault();});
document.addEventListener("click",event=>{if(event.target.matches("[data-close-modal]")){if(event.target.classList.contains("modal-backdrop")||event.target.closest(".modal"))closeModal();}});
function closeModal(){modalRoot.innerHTML="";}
function group(label,name,value="",type="text",options={}){const idName=`field-${name}`;let field;if(type==="select"){field=`<select class="select-field" id="${idName}" name="${name}" ${options.required?"required":""}>${options.items||""}</select>`;}else if(type==="textarea"){field=`<textarea id="${idName}" name="${name}" ${options.required?"required":""} maxlength="${options.maxlength||2000}" placeholder="${escapeHtml(options.placeholder||"")}">${escapeHtml(value)}</textarea>`;}else{field=`<input class="field" id="${idName}" name="${name}" type="${type}" value="${escapeHtml(value)}" ${options.min!==undefined?`min="${options.min}"`:""} ${options.max!==undefined?`max="${options.max}"`:""} ${options.required?"required":""} ${options.maxlength?`maxlength="${options.maxlength}"`:""} ${options.step?`step="${options.step}"`:""} placeholder="${escapeHtml(options.placeholder||"")}">`;}return `<div class="form-group ${options.full?"full":""}"><label for="${idName}">${escapeHtml(label)}</label>${field}${options.help?`<span class="help-text">${escapeHtml(options.help)}</span>`:""}</div>`;}
function subjectOptions(selected="",allowBlank=false){const subjects=read("subjects");return `${allowBlank?`<option value="">No subject</option>`:""}${subjects.map(s=>`<option value="${escapeHtml(s.id)}" ${selected===s.id?"selected":""}>${escapeHtml(s.name)}</option>`).join("")}`;}
function openSubjectForm(subjectId=null){const existing=read("subjects").find(s=>s.id===subjectId),s=existing||{};openModal(existing?"Edit subject":"Add subject",{kind:"subject",fields:group("Subject name","name",s.name||"","text",{required:true,maxlength:60,full:true,placeholder:"e.g. JavaScript"})+group("Description","description",s.description||"","textarea",{full:true,placeholder:"What are you learning in this subject?"})+group("Target score (%)","targetScore",s.targetScore||"","number",{min:0,max:100,placeholder:"Optional"})+group("Color","color",safeColor(s.color)||"#8b5cf6","color")+`<input type="hidden" name="id" value="${escapeHtml(s.id||"")}">`});}
function openScoreForm(scoreId=null,subjectId=""){const existing=read("scores").find(s=>s.id===scoreId),s=existing||{};if(!read("subjects").length){openModal("Add a subject first",{kind:"info",fields:`<div class="form-group full"><p class="muted">Scores need a subject so you can review performance by class.</p><button type="button" class="btn btn-primary" data-action="add-subject">＋ Add subject</button></div>`},"Close");return;}const types=["exam","quiz","assignment","midterm","final","project","other"],typeOpts=types.map(t=>`<option value="${t}" ${(s.type||"exam")===t?"selected":""}>${t[0].toUpperCase()+t.slice(1)}</option>`).join("");openModal(existing?"Edit assessment":"Add assessment",{kind:"score",fields:group("Assessment title","title",s.title||"","text",{required:true,maxlength:80})+group("Subject","subjectId",s.subjectId||subjectId,"select",{required:true,items:subjectOptions(s.subjectId||subjectId)})+group("Assessment type","type",s.type||"exam","select",{items:typeOpts})+group("Obtained score","obtained",s.obtained??"","number",{required:true,min:0,step:"any"})+group("Maximum score","maximum",s.maximum??100,"number",{required:true,min:.01,step:"any"})+group("Assessment date","date",s.date||todayISO(),"date",{required:true})+group("Notes","notes",s.notes||"","textarea",{full:true,placeholder:"Optional details"})+`<input type="hidden" name="id" value="${escapeHtml(s.id||"")}">`},existing?"Save changes":"Save assessment",true);}
function openTaskForm(taskId=null,dateOverride=""){const existing=read("tasks").find(t=>t.id===taskId),t=existing||{};const categories=["study","assignment","exam"].map(x=>`<option value="${x}" ${(t.category||"study")===x?"selected":""}>${x[0].toUpperCase()+x.slice(1)}</option>`).join("");const priorities=["low","medium","high"].map(x=>`<option value="${x}" ${(t.priority||"medium")===x?"selected":""}>${x[0].toUpperCase()+x.slice(1)}</option>`).join("");openModal(existing?"Edit study task":"Add study task",{kind:"task",fields:group("Task title","title",t.title||"","text",{required:true,maxlength:90,full:true})+group("Category","category",t.category||"study","select",{items:categories})+group("Subject","subjectId",t.subjectId||"","select",{items:subjectOptions(t.subjectId,true)})+group("Study date","date",t.date||dateOverride||todayISO(),"date",{required:true})+group("Estimated minutes","duration",t.duration??30,"number",{required:true,min:0,max:1440})+group("Priority","priority",t.priority||"medium","select",{items:priorities})+group("Description","description",t.description||"","textarea",{full:true,placeholder:"Optional notes for this task"})+`<input type="hidden" name="id" value="${escapeHtml(t.id||"")}">`},existing?"Save changes":"Add task",true);}
function openGoalForm(goalId=null){const existing=read("goals").find(g=>g.id===goalId),g=existing||{};const periods=["Daily","Weekly","Monthly","Personal"].map(x=>`<option value="${x.toLowerCase()}" ${(g.period||"weekly")===x.toLowerCase()?"selected":""}>${x}</option>`).join("");openModal(existing?"Edit study goal":"Create study goal",{kind:"goal",fields:group("Goal title","title",g.title||"","text",{required:true,maxlength:90,full:true,placeholder:"e.g. Practice JavaScript"})+group("Description","description",g.description||"","text",{maxlength:120,placeholder:"Optional detail"})+group("Subject","subjectId",g.subjectId||"","select",{items:subjectOptions(g.subjectId,true)})+group("Goal period","period",g.period||"weekly","select",{items:periods})+group("Target","target",g.target??5,"number",{required:true,min:1})+group("Current progress","current",g.current??0,"number",{required:true,min:0})+group("Unit","unit",g.unit||"sessions","text",{required:true,maxlength:24,placeholder:"minutes, sessions, lessons…"})+`<input type="hidden" name="id" value="${escapeHtml(g.id||"")}">`},existing?"Save changes":"Create goal",true);}
function openProgressForm(goalId){const goal=read("goals").find(g=>g.id===goalId);if(!goal)return;openModal("Add goal progress",{kind:"progress",fields:`<div class="form-group full"><label>Current progress</label><p class="muted">${escapeHtml(goal.title)} · ${Number(goal.current)||0} / ${Number(goal.target)||0} ${escapeHtml(goal.unit||"")}</p></div>`+group(`Add ${goal.unit||"units"}`,"increment","1","number",{required:true,min:.01,step:"any"})+`<input type="hidden" name="id" value="${escapeHtml(goal.id)}">`},"Add progress");}
function openNoteForm(noteId=null){const existing=read("notes").find(n=>n.id===noteId),n=existing||{},content=sanitizeNoteHtml(n.body||""),plain=content.replace(/<[^>]*>/g," ").replace(/\s+/g," ").trim();openModal(existing?"Edit document":"Create study document",{kind:"note",fields:group("Document title","title",n.title||"","text",{required:true,maxlength:90,full:true,placeholder:"e.g. JavaScript functions — class notes"})+group("Subject","subjectId",n.subjectId||"","select",{items:subjectOptions(n.subjectId,true)})+`<div class="form-group full note-document-group"><label for="note-document-editor">Document</label><div class="note-editor-shell"><div class="note-editor-toolbar" role="toolbar" aria-label="Document formatting"><button type="button" data-note-command="bold" title="Bold"><b>B</b></button><button type="button" data-note-command="italic" title="Italic"><i>I</i></button><button type="button" data-note-command="underline" title="Underline"><u>U</u></button><span></span><button type="button" data-note-command="formatBlock" data-value="h2" title="Heading">H₂</button><button type="button" data-note-command="formatBlock" data-value="h3" title="Subheading">H₃</button><span></span><button type="button" data-note-command="insertUnorderedList" title="Bulleted list">• List</button><button type="button" data-note-command="insertOrderedList" title="Numbered list">1. List</button><button type="button" data-note-command="formatBlock" data-value="blockquote" title="Quote">❝ Quote</button><button type="button" data-note-command="removeFormat" title="Clear formatting">Clear</button></div><div class="note-document-editor" id="note-document-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Study document content" data-placeholder="Start writing your notes here…">${content}</div></div><div class="note-editor-status"><span>Formatting saves with your document</span><span id="note-word-count">${plain?plain.split(/\s+/).filter(Boolean).length:0} words</span></div><textarea class="hidden" name="body" maxlength="30000">${escapeHtml(content)}</textarea></div><input type="hidden" name="id" value="${escapeHtml(n.id||"")}">`},existing?"Save changes":"Save document",true);}
function updateNoteWordCount(){const editor=document.getElementById("note-document-editor"),count=document.getElementById("note-word-count");if(!editor||!count)return;const words=(editor.innerText||"").trim().split(/\s+/).filter(Boolean).length;count.textContent=`${words} word${words===1?"":"s"}`;}

function quizQuestionMarkup(index){return `<section class="quiz-question-editor" data-quiz-question><div class="quiz-question-editor-head"><b class="quiz-question-number">Question ${index+1}</b><button type="button" class="text-action delete" data-action="remove-quiz-question">Remove</button></div><div class="form-group full"><label>Question</label><textarea class="quiz-prompt" maxlength="500" rows="2" required placeholder="Write a clear question…"></textarea></div><div class="quiz-options-grid">${[0,1,2,3].map(option=>`<label class="quiz-option-field"><span>${String.fromCharCode(65+option)}</span><input class="field quiz-option-input" maxlength="160" required placeholder="Answer option ${option+1}"></label>`).join("")}</div><div class="form-group"><label>Correct answer</label><select class="select-field quiz-correct-answer">${[0,1,2,3].map(option=>`<option value="${option}">Option ${String.fromCharCode(65+option)}</option>`).join("")}</select></div></section>`;}
function openQuizForm(classId){if(!classId)return notify("Open a class first","error");openModal("Create a class quiz",{kind:"class-quiz",fields:group("Quiz title","title","","text",{required:true,maxlength:100,full:true,placeholder:"e.g. JavaScript basics review"})+group("Due date","due_date",todayISO(),"date",{required:true,help:"Students will see this date in the class calendar."})+group("Instructions","instructions","","textarea",{full:true,maxlength:2000,placeholder:"Tell students what to expect."})+`<div class="form-group full quiz-builder-heading"><div><label>Questions</label><small>Add as many as you need, up to 100.</small></div><button type="button" class="btn btn-small btn-soft" data-action="add-quiz-question">＋ Add question</button></div><div class="form-group full quiz-question-list" id="quiz-question-list">${quizQuestionMarkup(0)}</div><input type="hidden" name="classId" value="${escapeHtml(classId)}">`},"Publish quiz",true);}
function renumberQuizQuestions(){document.querySelectorAll("#quiz-question-list [data-quiz-question]").forEach((row,index)=>{const label=row.querySelector(".quiz-question-number");if(label)label.textContent=`Question ${index+1}`;});}
function appendQuizQuestion(){const list=document.getElementById("quiz-question-list");if(!list)return;const rows=list.querySelectorAll("[data-quiz-question]");if(rows.length>=100)return notify("A quiz can have up to 100 questions","error");list.insertAdjacentHTML("beforeend",quizQuestionMarkup(rows.length));list.lastElementChild?.querySelector("textarea")?.focus();}
function removeQuizQuestion(button){const row=button.closest("[data-quiz-question]"),list=document.getElementById("quiz-question-list");if(!row||!list)return;if(list.querySelectorAll("[data-quiz-question]").length<=1)return notify("A quiz needs at least one question","error");row.remove();renumberQuizQuestions();}
async function openQuizAttempt(quizId){try{const{quiz}=await getQuiz(quizId);if(quiz.attempt){notify("You already submitted this quiz","error");return;}const questions=quiz.questions||[];if(!questions.length)return notify("This quiz has no questions","error");const due=quiz.due_date?` · Due ${formatDate(quiz.due_date,{month:"short",day:"numeric",year:"numeric"})}`:"";const fields=`<div class="quiz-attempt-intro"><span class="quiz-tag">${questions.length} QUESTION${questions.length===1?"":"S"}${due}</span><p>${escapeHtml(quiz.instructions||"Choose one answer for each question. Your answers are checked when you submit.")}</p></div>${questions.map((question,index)=>`<fieldset class="quiz-attempt-question"><legend><span>${index+1}</span>${escapeHtml(question.prompt)}</legend><div class="quiz-answer-options">${question.options.map((option,optionIndex)=>`<label class="quiz-answer-option"><input type="radio" name="answer-${index}" value="${optionIndex}" required><span>${escapeHtml(option)}</span></label>`).join("")}</div></fieldset>`).join("")}<input type="hidden" name="quizId" value="${escapeHtml(quiz.id)}">`;openModal(quiz.title,{kind:"quiz-attempt",fields},"Submit answers",true);}catch(error){notify(error.message||"Could not open this quiz","error");}}
async function openQuizResults(quizId){try{const[{attempts=[]},{quiz}]=await Promise.all([quizAttempts(quizId),getQuiz(quizId)]);const rows=attempts.length?`<div class="quiz-results-list">${attempts.map((attempt,index)=>`<div class="quiz-result-row"><span class="quiz-result-rank">${index+1}</span><b>${escapeHtml(attempt.student_name)}</b><span>${Number(attempt.correct_count)} / ${Number(attempt.question_count)} correct</span><strong>${Number(attempt.percentage).toFixed(0)}%</strong><small>${formatDate(attempt.submitted_at,{month:"short",day:"numeric",year:"numeric"})}</small></div>`).join("")}</div>`:`<div class="quiz-results-empty">No students have submitted this quiz yet.</div>`;openModal("Quiz results · "+quiz.title,{kind:"info",fields:`<div class="form-group full"><div class="quiz-results-summary"><span>${attempts.length}</span><small>student${attempts.length===1?"":"s"} submitted</small></div>${rows}</div>`},"Done",true);}catch(error){notify(error.message||"Could not load quiz results","error");}}

function quizReviewMarkup(review){if(!Array.isArray(review)||!review.length)return `<div class="quiz-results-empty">Answer review is unavailable for this attempt.</div>`;return `<div class="quiz-review-list">${review.map((item,index)=>{const selected=Number.isInteger(item.selected_index)?item.options[item.selected_index]:"No answer",correct=item.options[item.correct_index]??"—";return `<article class="quiz-review-item ${item.correct?"is-correct":"is-wrong"}"><div class="quiz-review-head"><span>Question ${index+1}</span><b>${item.correct?"✓ Correct":"✕ Review"}</b></div><p>${escapeHtml(item.prompt)}</p><div class="quiz-review-answer"><small>Your answer</small><strong>${escapeHtml(String(selected))}</strong></div>${item.correct?"":`<div class="quiz-review-correct"><small>Correct answer</small><strong>${escapeHtml(String(correct))}</strong></div>`}</article>`;}).join("")}</div>`;}
async function openStudentQuizReview(quizId){try{const{quiz}=await getQuiz(quizId),attempt=quiz?.attempt;if(!attempt)return notify("Submit the quiz first to review answers","error");const pct=Math.round(100*Number(attempt.correct_count)/Math.max(1,Number(attempt.question_count)));openModal("Your quiz result · "+quiz.title,{kind:"info",fields:`<div class="form-group full"><div class="quiz-finish-card"><span class="quiz-finish-spark">${pct===100?"✦":"✓"}</span><strong>${pct}%</strong><b>${Number(attempt.correct_count)} of ${Number(attempt.question_count)} correct</b><p>${pct===100?"Perfect work — every answer is correct.":"Review the answers below to see what you got right and what to practice next."}</p></div>${quizReviewMarkup(attempt.review)}</div>`},"Done",true);}catch(error){notify(error.message||"Could not load your quiz review","error");}}

