function openAssignmentForm(classId){if(!classId)return notify("Open a class first","error");openModal("Create assignment",{kind:"class-assignment",fields:group("Assignment title","title","","text",{required:true,maxlength:100,full:true,placeholder:"e.g. JavaScript DOM practice"})+group("Subject","subject","","text",{maxlength:60,placeholder:"Optional subject"})+group("Due date","due_date",todayISO(),"date",{required:true})+group("Maximum score","maximum","100","number",{required:true,min:1,max:10000,step:"any"})+group("Instructions","instructions","","textarea",{full:true,maxlength:3000,placeholder:"Explain what students need to complete."})+`<input type="hidden" name="classId" value="${escapeHtml(classId)}">`},"Post assignment",true);}
function openStudentSubmissionForm(classId,assignmentId){submissionFiles=[];openModal("Submit class work",{kind:"class-submission",fields:group("Comment for your teacher (optional)","notes","","textarea",{full:true,maxlength:2000,placeholder:"Add a short message or submission note."})+`<div class="form-group full"><label>Attach files or a folder</label><div class="submission-upload-zone" data-submission-drop><div class="upload-cloud">↥</div><b>Drop your work here</b><small>Choose individual files or upload a whole folder.</small><div class="upload-actions"><label class="btn btn-small btn-soft" for="submission-files">＋ Choose files</label><label class="btn btn-small" for="submission-folder">▣ Choose folder</label><input id="submission-files" class="hidden" type="file" multiple><input id="submission-folder" class="hidden" type="file" multiple webkitdirectory directory></div></div><div class="submission-file-list" id="submission-file-list" aria-live="polite"></div><span class="help-text">Up to 20 files · 8 MB each · 12 MB total. File names and folder paths are saved with your submission.</span></div><input type="hidden" name="classId" value="${escapeHtml(classId)}"><input type="hidden" name="assignmentId" value="${escapeHtml(assignmentId)}">`},"Submit work",true);renderSubmissionFileList();}
function openGradeSubmissionForm(classId,submissionId,maximum,currentScore="",feedback=""){openModal("Review student submission",{kind:"class-grade",fields:group(`Score out of ${Number(maximum)} (optional)`,"score",currentScore,"number",{min:0,max:Number(maximum),step:"any",full:true,placeholder:"Leave blank to reply without grading"})+group("Comment for the student","feedback",feedback,"textarea",{full:true,maxlength:2000,placeholder:"Share feedback or next steps."})+`<input type="hidden" name="classId" value="${escapeHtml(classId)}"><input type="hidden" name="submissionId" value="${escapeHtml(submissionId)}">`},"Save review",true);}

function addSubmissionFiles(incoming){const maxFile=8*1024*1024,maxTotal=12*1024*1024,maxCount=20,known=new Set(submissionFiles.map(file=>file.webkitRelativePath||file.name));let total=submissionFiles.reduce((sum,file)=>sum+file.size,0),added=0;for(const file of incoming){const name=file.webkitRelativePath||file.name;if(known.has(name))continue;if(file.size>maxFile){notify(`${file.name} is larger than 8 MB and was skipped`,"error");continue;}if(submissionFiles.length>=maxCount){notify("You can attach up to 20 files","error");break;}if(total+file.size>maxTotal){notify("Attachments must total no more than 12 MB","error");continue;}submissionFiles.push(file);known.add(name);total+=file.size;added++;}if(added)notify(`${added} file${added===1?"":"s"} added`);renderSubmissionFileList();}
function removeSubmissionFile(index){if(index<0||index>=submissionFiles.length)return;submissionFiles.splice(index,1);renderSubmissionFileList();}
function renderSubmissionFileList(){const list=document.getElementById("submission-file-list");if(!list)return;list.innerHTML=submissionFiles.length?submissionFiles.map((file,index)=>`<div class="selected-upload"><span class="upload-file-icon">▤</span><span class="upload-file-name" title="${escapeHtml(file.webkitRelativePath||file.name)}">${escapeHtml(file.webkitRelativePath||file.name)}</span><small>${formatUploadSize(file.size)}</small><button type="button" class="upload-remove" data-action="remove-submission-file" data-index="${index}" aria-label="Remove ${escapeHtml(file.name)}">×</button></div>`).join(""):`<div class="upload-list-empty">No files selected yet.</div>`;}
function formatUploadSize(size){return size<1024?`${size} B`:size<1048576?`${(size/1024).toFixed(1)} KB`:`${(size/1048576).toFixed(1)} MB`;}
async function encodeSubmissionFile(file){const bytes=new Uint8Array(await file.arrayBuffer()),parts=[];for(let i=0;i<bytes.length;i+=32768)parts.push(String.fromCharCode(...bytes.subarray(i,i+32768)));return{name:file.webkitRelativePath||file.name,data:btoa(parts.join(""))};}

async function handleClassChatSubmit(form){const data=new FormData(form),body=String(data.get("body")||"").trim(),classId=form.dataset.classId,recipientId=form.dataset.recipientId,button=form.querySelector("button[type=submit]");if(!body)return;if(button){button.disabled=true;button.textContent="Sending…";}try{await sendClassMessage(classId,recipientId,body);form.reset();const {messages=[]}=await classMessages(classId,recipientId);const currentForm=document.getElementById("class-chat-form");if(currentForm?.dataset.recipientId===recipientId){const feed=currentForm.closest(".chat-conversation")?.querySelector("[data-chat-feed]");if(feed){feed.innerHTML=renderChatMessages(messages,currentUser()?.id||"");feed.scrollTop=feed.scrollHeight;}}}catch(error){notify(error.message||"Could not send your message","error");}finally{if(button?.isConnected){button.disabled=false;button.innerHTML="Send <span>↑</span>";}}}

async function handleModalSubmit(form,kind){if(kind==="info"){closeModal();return;}const data=new FormData(form),get=name=>String(data.get(name)||"").trim(),idField=get("id");
  if(kind==="class-create"){try{await createClass(get("name"));closeModal();notify("Class created — share its join code with students");navigate("classroom");}catch(error){notify(error.message,"error");}return;}
  if(kind==="class-join"){try{await joinClass(get("code"));closeModal();notify("You joined the class");selectClass("");navigate("classroom");}catch(error){notify(error.message,"error");}return;}
  if(kind==="class-assignment"){try{await createAssignment(get("classId"),{title:get("title"),subject:get("subject"),due_date:get("due_date"),maximum:Number(get("maximum")),instructions:get("instructions")});closeModal();notify("Assignment posted for your class");navigate("classroom");}catch(error){notify(error.message,"error");}return;}
  if(kind==="class-submission"){const button=form.querySelector("button[type=submit]");if(button){button.disabled=true;button.textContent="Uploading…";}try{const files=await Promise.all(submissionFiles.map(encodeSubmissionFile));await submitAssignment(get("classId"),{assignment_id:get("assignmentId"),notes:get("notes"),files});submissionFiles=[];closeModal();notify("Your work was submitted");navigate("classroom");}catch(error){notify(error.message||"Could not submit your work","error");}finally{if(button?.isConnected){button.disabled=false;button.textContent="Submit work";}}return;}
  if(kind==="class-grade"){const score=get("score");try{await gradeSubmission(get("classId"),get("submissionId"),score===""?null:Number(score),get("feedback"));closeModal();notify("Review saved");navigate("classroom");}catch(error){notify(error.message,"error");}return;}
  if(kind==="class-quiz"){
    const questions=[...form.querySelectorAll("[data-quiz-question]")].map(row=>({prompt:row.querySelector(".quiz-prompt")?.value.trim()||"",options:[...row.querySelectorAll(".quiz-option-input")].map(input=>input.value.trim()),correctIndex:Number(row.querySelector(".quiz-correct-answer")?.value)}));
    if(!questions.length||questions.some(question=>question.prompt.length<2||question.options.length<2||question.options.some(option=>!option)))return notify("Add a question and fill in all four answer options","error");
    const button=form.querySelector("button[type=submit]");if(button){button.disabled=true;button.textContent="Publishing…";}
    try{await createQuiz(get("classId"),{title:get("title"),instructions:get("instructions"),due_date:get("due_date"),questions});closeModal();notify("Quiz published to your class");navigate("classroom");}catch(error){notify(error.message||"Could not publish quiz","error");}finally{if(button?.isConnected){button.disabled=false;button.textContent="Publish quiz";}}return;
  }
  if(kind==="quiz-attempt"){
    const questions=[...form.querySelectorAll("[name^='answer-']")],answerCount=new Set(questions.map(input=>input.name)).size;
    const answers=Array.from({length:answerCount},(_,index)=>{const selected=form.querySelector(`[name="answer-${index}"]:checked`);return selected?Number(selected.value):null;});
    if(answers.some(answer=>answer===null))return notify("Choose an answer for every question","error");
    const button=form.querySelector("button[type=submit]");if(button){button.disabled=true;button.textContent="Checking answers…";}
    try{const result=await submitQuiz(get("quizId"),answers),pct=Math.round(Number(result.percentage)||0);closeModal();navigate("classroom");openModal("Quiz submitted",{kind:"info",fields:`<div class="form-group full"><div class="quiz-finish-card"><span class="quiz-finish-spark">${pct===100?"✦":"✓"}</span><strong>${pct}%</strong><b>${Number(result.correct_count)||0} of ${Number(result.question_count)||0} answers correct</b><p>${pct===100?"Excellent work — every answer is correct.":"Your score is saved. Review the correct answers below to keep learning."}</p></div>${quizReviewMarkup(result.review)}</div>`},"Done",true);}catch(error){notify(error.message||"Could not submit quiz answers","error");}finally{if(button?.isConnected){button.disabled=false;button.textContent="Submit answers";}}return;
  }
  if(kind==="subject"){
    const name=get("name"),records=read("subjects");if(records.some(s=>s.id!==idField&&s.name.toLowerCase()===name.toLowerCase()))return notify("A subject with that name already exists","error");const current=records.find(s=>s.id===idField),item={id:idField||id(),name,description:get("description"),targetScore:get("targetScore")?Number(get("targetScore")):null,color:safeColor(get("color"))||"#8b5cf6",createdAt:current?.createdAt||new Date().toISOString()};write("subjects",current?records.map(s=>s.id===idField?item:s):[...records,item]);closeModal();notify(current?"Subject updated":"Subject added");refresh();return;
  }
  if(kind==="score"){
    const obtained=Number(get("obtained")),maximum=Number(get("maximum"));if(!Number.isFinite(obtained)||!Number.isFinite(maximum)||maximum<=0||obtained<0||obtained>maximum)return notify("Enter a score from 0 up to the maximum score","error");const records=read("scores"),current=records.find(s=>s.id===idField),item={id:idField||id(),subjectId:get("subjectId"),title:get("title"),type:get("type"),obtained,maximum,date:get("date"),notes:get("notes"),createdAt:current?.createdAt||new Date().toISOString()};write("scores",current?records.map(s=>s.id===idField?item:s):[...records,item]);closeModal();notify(current?"Assessment updated":"Assessment saved");syncAchievements();refresh();return;
  }
  if(kind==="task"){
    const records=read("tasks"),current=records.find(t=>t.id===idField),item={id:idField||id(),title:get("title"),category:get("category"),subjectId:get("subjectId")||null,date:get("date"),duration:Number(get("duration")),priority:get("priority"),description:get("description"),completed:current?.completed||false,completedAt:current?.completedAt||null,createdAt:current?.createdAt||new Date().toISOString()};if(!item.date||item.duration<0)return notify("Choose a date and non-negative duration","error");write("tasks",current?records.map(t=>t.id===idField?item:t):[...records,item]);closeModal();notify(current?"Task updated":"Task added to planner");refresh();return;
  }
  if(kind==="goal"){
    const target=Number(get("target")),currentValue=Number(get("current"));if(target<=0||currentValue<0)return notify("Enter a positive target and valid progress","error");const records=read("goals"),current=records.find(g=>g.id===idField),item={id:idField||id(),title:get("title"),description:get("description"),subjectId:get("subjectId")||null,period:get("period"),target,current:currentValue,unit:get("unit"),createdAt:current?.createdAt||new Date().toISOString()};write("goals",current?records.map(g=>g.id===idField?item:g):[...records,item]);closeModal();syncAchievements();notify(current?"Goal updated":"Goal created");refresh();return;
  }
  if(kind==="progress"){
    const increment=Number(get("increment"));const goals=read("goals"),goal=goals.find(g=>g.id===idField);if(!goal||increment<=0)return notify("Enter a progress amount greater than zero","error");write("goals",goals.map(g=>g.id===idField?{...g,current:Number(g.current||0)+increment}:g));closeModal();syncAchievements();notify("Goal progress updated");refresh();return;
  }
  if(kind==="note"){
    const editor=form.querySelector("#note-document-editor"),body=sanitizeNoteHtml(editor?.innerHTML||get("body")),plain=body.replace(/<[^>]*>/g," ").replace(/\s+/g," ").trim();if(!plain)return notify("Write a little in your document before saving","error");if(plain.length>10000)return notify("Keep each document under 10,000 characters","error");
    const records=read("notes"),current=records.find(n=>n.id===idField),item={id:idField||id(),title:get("title"),subjectId:get("subjectId")||null,body,updatedAt:new Date().toISOString(),createdAt:current?.createdAt||new Date().toISOString()};write("notes",current?records.map(n=>n.id===idField?item:n):[item,...records]);closeModal();notify(current?"Document updated":"Document saved");refresh();return;
  }
}

function toggleTask(taskId){const tasks=read("tasks");write("tasks",tasks.map(t=>t.id===taskId?{...t,completed:!t.completed,completedAt:!t.completed?new Date().toISOString():null}:t));syncAchievements();refresh();}
function deleteRecord(collection,recordId,label){if(!window.confirm(`Delete this ${label}? This cannot be undone.`))return;write(collection,read(collection).filter(x=>x.id!==recordId));syncAchievements();notify(`${label[0].toUpperCase()+label.slice(1)} deleted`);refresh();}
function deleteSubject(subjectId){const subject=read("subjects").find(s=>s.id===subjectId);if(!subject)return;if(!window.confirm(`Delete “${subject.name}”? Related scores, tasks, notes, and goals will be kept without a subject.`))return;write("subjects",read("subjects").filter(s=>s.id!==subjectId));for(const group of ["scores","tasks","notes","goals"])write(group,read(group).map(item=>item.subjectId===subjectId?{...item,subjectId:null}:item));notify("Subject deleted; related records were kept");refresh();}
function saveTimerDurations(focusId,shortId,longId){const values=[focusId,shortId,longId].map(x=>Number(document.getElementById(x).value));if(values.some(x=>!Number.isInteger(x)||x<1))return notify("Timer durations must be whole minutes greater than zero","error");saveDurations(...values);notify("Timer durations saved");refresh();}
function savePreferences(){const values=["settings-focus","settings-short","settings-long"].map(x=>Number(document.getElementById(x).value));if(values.some(x=>!Number.isInteger(x)||x<1))return notify("Timer durations must be whole minutes greater than zero","error");saveDurations(...values);notify("Preferences saved");refresh();}
function toggleTheme(){const settings=getSettings();settings.theme=settings.theme==="dark"?"light":"dark";saveSettings(settings);syncTheme();if(currentPage==="settings")refresh();}
function exportBackup(){const blob=new Blob([JSON.stringify({app:"StudyTrack",version:1,exportedAt:new Date().toISOString(),...allData()},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),anchor=document.createElement("a");anchor.href=url;anchor.download=`studytrack-backup-${todayISO()}.json`;anchor.click();URL.revokeObjectURL(url);notify("Backup downloaded");}
async function importBackup(file){try{if(file.size>5*1024*1024)throw new Error("Backup must be smaller than 5 MB.");const data=JSON.parse(await file.text());if(!window.confirm("Import this backup? Matching StudyTrack data categories will be replaced with the backup contents."))return;importData(data);notify("Backup imported");syncAchievements();syncTheme();refresh();}catch(error){notify(error.message||"Could not read this backup","error");}finally{document.getElementById("import-file").value="";}}
async function clearApplicationData(){if(!window.confirm("Delete all StudyTrack study data from this account on every device? This removes subjects, scores, tasks, sessions, notes, goals, and settings. Export a backup first if you may need these records."))return;try{await deleteRemoteData();clearAll();window.location.reload();}catch(error){notify(error.message||"Could not delete account data","error");}}
function safeColor(value){return /^#[0-9a-f]{6}$/i.test(value||"")?value:"#8b5cf6";}

async function hashPin(pin){if(globalThis.crypto?.subtle){const data=new TextEncoder().encode(`StudyTrack-local-pin-v1:${pin}`),digest=await crypto.subtle.digest("SHA-256",data);return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,"0")).join("");}return [...pin].reduce((n,c)=>Math.imul(n^c.charCodeAt(0),16777619)>>>0,2166136261).toString(16);}
function openPinSetup(){openModal("Set a local PIN",{kind:"pin-setup",fields:group("Choose a 4–12 digit PIN","pin","","password",{required:true,minlength:4,maxlength:12,full:true,placeholder:"••••"})+group("Confirm PIN","confirm","","password",{required:true,minlength:4,maxlength:12,full:true,placeholder:"Enter the PIN again"})+`<div class="form-group full"><span class="help-text">This is a casual lock only. It does not encrypt your LocalStorage data.</span></div>`},"Enable PIN");}
async function disablePin(){if(!window.confirm("Disable the local PIN lock?"))return;const settings=getSettings();settings.pinEnabled=false;settings.pinHash="";saveSettings(settings);notify("PIN lock disabled");refresh();}
function renderLock(){document.getElementById("lock-screen").classList.remove("hidden");document.getElementById("lock-screen").innerHTML=`<div class="lock-card"><div class="brand-mark"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21.5v-16Z"/><path d="M4 17.5A2.5 2.5 0 0 1 6.5 15H20M8 7h8M8 10h6"/></svg></div><h2>Welcome back</h2><p>Enter your StudyTrack local PIN to continue.</p><form id="unlock-form"><input class="field" id="unlock-pin" type="password" inputmode="numeric" autocomplete="current-password" maxlength="12" placeholder="Enter your PIN" required><div class="lock-error" id="lock-error"></div><button class="btn btn-primary" style="width:100%">Unlock StudyTrack</button></form><p style="margin-top:13px;font-size:8px">This PIN lock is for casual privacy and does not encrypt saved data.</p></div>`;document.getElementById("unlock-pin").focus();}

function renderOAuthButtons(){return `<div class="oauth-divider"><span>or continue with</span></div><div class="oauth-login-grid"><a class="oauth-login-button" href="/auth/google"><span class="oauth-logo google" aria-hidden="true"><svg viewBox="0 0 48 48"><path fill="#4285F4" d="M43.6 20.1H42V20H24v8h11.3A12 12 0 0 1 24 36.5v8c11.3 0 20.5-9.2 20.5-20.5 0-1.3-.1-2.6-.4-3.9Z"/><path fill="#34A853" d="M24 44.5v-8a12.5 12.5 0 0 1-10.7-6l-6.8 5.2A20.4 20.4 0 0 0 24 44.5Z"/><path fill="#FBBC05" d="M13.3 30.5a12.5 12.5 0 0 1 0-13l-6.8-5.2a20.4 20.4 0 0 0 0 23.4l6.8-5.2Z"/><path fill="#EA4335" d="M24 11.5c3.1 0 5.9 1.2 8.1 3.1l5.7-5.7A20.3 20.3 0 0 0 24 3.5 20.4 20.4 0 0 0 6.5 12.3l6.8 5.2A12.5 12.5 0 0 1 24 11.5Z"/></svg></span><span>Google</span></a><a class="oauth-login-button" href="/auth/github"><span class="oauth-logo github" aria-hidden="true"><svg viewBox="0 0 24 24"><path fill="currentColor" d="M12 .8a11.2 11.2 0 0 0-3.54 21.83c.56.1.76-.24.76-.54v-2.1c-3.1.68-3.75-1.32-3.75-1.32-.51-1.29-1.24-1.63-1.24-1.63-1.02-.7.08-.68.08-.68 1.13.08 1.73 1.16 1.73 1.16 1 1.72 2.63 1.22 3.27.93.1-.72.4-1.22.71-1.5-2.48-.28-5.09-1.24-5.09-5.53 0-1.22.44-2.22 1.16-3-.12-.29-.5-1.43.11-2.98 0 0 .95-.3 3.08 1.15a10.7 10.7 0 0 1 5.61 0c2.13-1.45 3.08-1.15 3.08-1.15.61 1.55.23 2.69.12 2.98.72.78 1.15 1.78 1.15 3 0 4.3-2.61 5.25-5.1 5.53.4.35.76 1.03.76 2.08v3.08c0 .3.2.65.77.54A11.2 11.2 0 0 0 12 .8Z"/></svg></span><span>GitHub</span></a><a class="oauth-login-button" href="/auth/telegram"><span class="oauth-logo telegram" aria-hidden="true"><svg viewBox="0 0 24 24"><path fill="currentColor" fill-rule="evenodd" d="M23.4 3.1a1 1 0 0 0-1.08-.16L1.1 11.8a1.1 1.1 0 0 0 .11 2.05l5.23 1.78 1.93 5.45a1.1 1.1 0 0 0 1.91.34l3.04-3.7 5.09 3.74a1.1 1.1 0 0 0 1.72-.67l3.54-16.56a1.1 1.1 0 0 0-.27-1.13ZM9.3 14.75l9.85-7.18-7.43 8.88-.37 3.02-2.05-4.72Z"/></svg></span><span>Telegram</span></a></div><p class="oauth-login-note">New Google/GitHub accounts start as Student. Connect Telegram once in Settings after signing in.</p>`;}
function authDraft(){return{name:authRoot.querySelector("#auth-name")?.value||"",email:authRoot.querySelector("#auth-email")?.value||""};}
function renderAuthScreen(mode="login",role="student",error="",draft={}){
  const registering=mode==="register",teacher=role==="teacher",admin=role==="admin";
  authRoot.classList.remove("hidden");authRoot.dataset.mode=mode;authRoot.dataset.role=role;delete authRoot.dataset.resetToken;
  authRoot.innerHTML=`<div class="auth-screen"><div class="auth-panel"><section class="auth-visual"><a class="auth-brand" href="#"><span class="brand-mark"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21.5z"/><path d="M4 17.5A2.5 2.5 0 0 1 6.5 15H20M8 7h8M8 10h6"/></svg></span><span>StudyTrack</span></a><div class="auth-visual-content"><span class="auth-kicker">STUDY WITH PURPOSE</span><h1>A brighter way to<br><em>make progress.</em></h1><p>Keep your study plan, achievements, and classroom work together in one welcoming space.</p><div class="auth-art"><div class="auth-art-orbit one"></div><div class="auth-art-orbit two"></div><div class="auth-art-card"><span class="auth-art-icon">✦</span><div class="auth-art-lines"><i></i><i></i><i></i></div><div class="auth-art-foot"><span>✓</span><b>One step at a time</b></div></div><span class="auth-art-star">✧</span></div><div class="auth-quote">“Little by little, a little becomes a lot.”</div></div><div class="auth-visual-footer"><span>Student, teacher, and admin accounts</span><span>Private classroom spaces</span></div></section><section class="auth-form-panel"><div class="auth-form-inner"><div class="auth-head-row"><div class="auth-welcome"><span class="auth-mobile-mark">✦</span><span class="eyebrow">${registering?"CREATE YOUR ACCOUNT":"WELCOME BACK"}</span><h2>${registering?"Start your journey":"Sign in to StudyTrack"}</h2><p>${registering?"Your personal learning space is ready when you are.":"Continue your learning right where you left off."}</p></div><div class="language-picker language-control auth-language-control" data-language-picker>
  <button type="button" class="language-picker-trigger" data-language-trigger aria-label="Choose language" aria-haspopup="menu" aria-expanded="false" title="Choose language">
    <span class="language-control-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/></svg></span>
    <span class="language-current" data-language-current>English</span>
    <span class="language-chevron" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m7 10 5 5 5-5"/></svg></span>
  </button>
  <div class="language-menu" data-language-menu role="menu" aria-label="Choose interface language" hidden>
    <button type="button" role="menuitemradio" data-language-option="en" aria-checked="true"><span>English</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg></button>
    <button type="button" role="menuitemradio" data-language-option="km" aria-checked="false"><span>ខ្មែរ</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg></button>
  </div>
</div></div><div class="auth-role-picker" role="group" aria-label="Choose account type"><button type="button" data-auth-role="student" class="${role==="student"?"active":""}">${iconMarkup("student")}Student</button><button type="button" data-auth-role="teacher" class="${role==="teacher"?"active":""}">${iconMarkup("teacher")}Teacher</button><button type="button" data-auth-role="admin" class="${admin?"active":""}">${iconMarkup("settings")}Admin</button></div><form id="auth-form" data-mode="${mode}" class="auth-form">${registering?`<div class="form-group"><label for="auth-name">Full name</label><input class="field" id="auth-name" name="name" autocomplete="name" maxlength="60" required placeholder="Your name" value="${escapeHtml(draft.name||"")}"></div>`:""}<div class="form-group"><label for="auth-email">Email address</label><input class="field" id="auth-email" name="email" type="email" autocomplete="email" maxlength="254" required placeholder="you@example.com" value="${escapeHtml(draft.email||"")}"></div><div class="form-group"><label for="auth-password">Password</label><input class="field" id="auth-password" name="password" type="password" autocomplete="${registering?"new-password":"current-password"}" minlength="10" maxlength="128" required placeholder="At least 10 characters">${registering?`<span class="help-text">Use at least 10 characters.</span>`:""}</div>${!registering?`<div class="auth-forgot-row"><button type="button" class="auth-forgot-link" data-auth-mode="forgot">Forgot password? Reset it</button></div>`:""}${registering&&teacher?`<div class="form-group"><label for="teacher-code">Teacher access code</label><input class="field" id="teacher-code" name="teacher_code" type="password" autocomplete="off" required placeholder="Provided by your app owner"><span class="help-text">This code protects teacher tools from public registration.</span></div>`:""}${registering&&admin?`<div class="form-group"><label for="admin-code">Admin access code</label><input class="field" id="admin-code" name="admin_code" type="password" autocomplete="off" required placeholder="Private code from the app owner"><span class="help-text">Admin registration is protected by the server owner.</span></div>`:""}<input type="hidden" name="role" value="${role}"><div class="auth-error ${error?"show":""}" role="alert">${error?`<span class="auth-error-icon" aria-hidden="true">!</span><span class="auth-error-message">${escapeHtml(error)}</span>${registering&&/already exists/i.test(error)?`<button type="button" class="auth-error-action" data-auth-mode="login">Sign in to this account</button>`:""}`:""}</div><button class="btn btn-primary auth-submit" type="submit">${registering?`Create ${admin?"admin":teacher?"teacher":"student"} account`:`Sign in as ${admin?"admin":teacher?"teacher":"student"}`} <span>→</span></button></form><div class="auth-switch">${registering?`Already have an account? <button type="button" data-auth-mode="login">Sign in</button>`:`New to StudyTrack? <button type="button" data-auth-mode="register">Create account</button>`}</div>${renderOAuthButtons()}<div class="auth-bottom"><button type="button" class="auth-about-link" data-action="about-modal">About this app</button><span><i></i> Your data syncs to your account</span></div><p class="auth-security-note">Use StudyTrack over HTTPS when it is deployed online. Your account is separate from your browser profile.</p></div></section></div></div>`;
  // Do not pop the mobile keyboard over the sign-in screen on page load.
  if(!window.matchMedia("(max-width: 760px)").matches&&!window.matchMedia("(pointer: coarse)").matches)authRoot.querySelector("#auth-email")?.focus();
}

function renderPasswordRecovery(mode="request",{email="",token="",error="",notice=""}={}){
  const resetting=mode==="reset";
  authRoot.classList.remove("hidden");authRoot.dataset.mode=mode;authRoot.dataset.role="student";authRoot.dataset.resetToken=resetting?token:"";
  authRoot.innerHTML=`<div class="auth-screen"><div class="auth-panel auth-recovery-panel"><section class="auth-form-panel"><div class="auth-form-inner"><div class="auth-recovery-brand"><span class="brand-mark auth-recovery-mark" aria-hidden="true">✦</span><span>StudyTrack</span></div><div class="auth-welcome auth-recovery-welcome"><span class="eyebrow">PASSWORD HELP</span><h2>${resetting?"Choose a new password":"Reset your password"}</h2><p>${resetting?"Use the form below to set a new password.":"Enter the email address on your StudyTrack account. We’ll send a one-time link."}</p></div><form id="auth-form" data-mode="${mode}" class="auth-form">${resetting?`<div class="form-group"><label for="reset-password">New password</label><input class="field" id="reset-password" name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required placeholder="At least 10 characters"><span class="help-text">Use at least 10 characters.</span></div><div class="form-group"><label for="reset-confirm">Confirm new password</label><input class="field" id="reset-confirm" name="confirm" type="password" autocomplete="new-password" minlength="10" maxlength="128" required placeholder="Enter the new password again"></div>`:`<div class="form-group"><label for="auth-email">Email address</label><input class="field" id="auth-email" name="email" type="email" autocomplete="email" maxlength="254" required placeholder="you@example.com" value="${escapeHtml(email)}"></div>`}<div class="auth-error ${error?"show":""}" role="alert">${error?`<span class="auth-error-icon" aria-hidden="true">!</span><span class="auth-error-message">${escapeHtml(error)}</span>`:""}</div>${notice?`<p class="auth-recovery-notice" role="status">${escapeHtml(notice)}</p>`:""}<button class="btn btn-primary auth-submit" type="submit">${resetting?"Save new password":"Send reset link"}</button></form><div class="auth-switch"><span>${resetting?"Reset link not working?":"Remember your password?"}</span> <button type="button" data-auth-mode="${resetting?"forgot":"login"}">${resetting?"Request a new link":"Back to sign in"}</button></div><p class="auth-security-note">Reset links expire after 30 minutes and can only be used once.</p></div></section></div></div>`;
  if(!window.matchMedia("(max-width: 760px)").matches&&!window.matchMedia("(pointer: coarse)").matches)authRoot.querySelector(resetting?"#reset-password":"#auth-email")?.focus();
}

async function handleAuthSubmit(event){
  if(event.target.id!=="auth-form")return;
  event.preventDefault();
  const form=new FormData(event.target),mode=event.target.dataset.mode,email=String(form.get("email")||"").trim(),password=String(form.get("password")||""),button=event.target.querySelector("button[type=submit]");
  if(button){button.disabled=true;button.classList.add("is-loading");}
  if(mode==="request"){
    try{await requestPasswordReset(email);renderPasswordRecovery("request",{email,notice:"If an account exists for this email, a reset link will arrive shortly. Check your inbox and spam folder."});}
    catch(error){renderPasswordRecovery("request",{email,error:error.message||"Could not request a password reset. Try again."});}
    return;
  }
  if(mode==="reset"){
    const token=authRoot.dataset.resetToken||"",confirmPassword=String(form.get("confirm")||"");
    if(password!==confirmPassword){renderPasswordRecovery("reset",{token,error:"The passwords do not match."});return;}
    try{await resetPassword(token,password);window.history.replaceState(null,"",window.location.pathname+window.location.search);renderAuthScreen("login","student");notify("Password updated. Sign in with your new password.");}
    catch(error){renderPasswordRecovery("reset",{token,error:error.message||"Could not reset the password. Request a new link."});}
    return;
  }
  const localSnapshot=allData(),payload={email,password,role:String(form.get("role")||"student")};
  if(mode==="register"){payload.name=String(form.get("name")||"").trim();payload.teacher_code=String(form.get("teacher_code")||"");payload.admin_code=String(form.get("admin_code")||"");}
  try{const response=await authenticate(mode,payload);await activateAccount(response,localSnapshot,mode==="register",true);}
  catch(error){if(authActive()){try{await logout();}catch{clearSession();}}renderAuthScreen(mode,payload.role,error.message||"Could not sign in. Try again.",{name:payload.name||"",email:payload.email});}
}

function containsStudyRecords(data){return ["subjects","scores","tasks","sessions","notes","goals"].some(key=>Array.isArray(data?.[key])&&data[key].length>0);}
function remoteHasRecords(data){return containsStudyRecords(data);}
async function activateAccount(session,localSnapshot,isNew,showWelcome=false){
  authRoot.innerHTML=`<div class="auth-loading"><span class="loading-orbit"></span><b>Setting up your private workspace…</b></div>`;
  const user=session.user,remote=await getRemoteData(),sameAccount=localStorage.getItem("studytrack_account_id")===user.id;
  const mayMigrate=user.role!=="admin"&&containsStudyRecords(localSnapshot)&&!remoteHasRecords(remote)&&(!sameAccount||isNew);
  let useLocal=false;
  if(mayMigrate)useLocal=window.confirm("This browser has study records that are not in this account yet. Upload them to this account? Choose Cancel to use the account's existing data instead.");
  if(useLocal){const migrated={...localSnapshot,profile:{...localSnapshot.profile,name:user.name,role:user.role,avatar:localSnapshot.profile?.avatar||user.name.slice(0,1).toUpperCase()}};await uploadData(migrated);replaceDataFromServer(migrated);}
  else replaceDataFromServer(remote);
  localStorage.setItem("studytrack_account_id",user.id);
  const profile=read("profile");if(profile.role!==user.role||!profile.name){write("profile",{...profile,name:user.name,role:user.role});}
  authRoot.classList.add("hidden");authRoot.innerHTML="";appShell.classList.remove("hidden");syncTheme();syncProfileChrome();setSyncStatus(true);navigate(user.role==="admin"?"admin":"dashboard");if(getSettings().pinEnabled)renderLock();else if(showWelcome)showArrivalWelcome(user,isNew);
}

function showArrivalWelcome(user,isNew){
  if(arrivalWelcomeTimer)clearTimeout(arrivalWelcomeTimer);
  document.querySelector(".arrival-welcome-screen")?.remove();
  const name=String(user?.name||"there").trim()||"there";
  const overlay=document.createElement("div");overlay.className="arrival-welcome-screen";overlay.setAttribute("role","dialog");overlay.setAttribute("aria-modal","true");overlay.setAttribute("aria-labelledby","arrival-welcome-title");
  overlay.innerHTML=`<button type="button" class="arrival-skip" data-action="skip-welcome">Skip intro <span aria-hidden="true">×</span></button><div class="arrival-welcome-content"><div class="arrival-book-scene" aria-hidden="true"><span class="arrival-book-orbit"></span><span class="arrival-floating-book one"><i></i><i></i></span><span class="arrival-floating-book two"><i></i><i></i></span><span class="arrival-floating-book three"><i></i><i></i></span><span class="arrival-scene-spark spark-one">✦</span><span class="arrival-scene-spark spark-two">✧</span><span class="arrival-scene-spark spark-three">✦</span><div class="arrival-open-book"><div class="arrival-book-pages"><div class="arrival-book-page left"><i></i><i></i><i></i><i></i><b>YOUR NEXT<br>CHAPTER</b></div><div class="arrival-book-page right"><i></i><i></i><i></i><i></i><span>✦</span></div></div><div class="arrival-book-cover"><span class="arrival-book-emblem">✦</span><b>StudyTrack</b><small>LEARNING JOURNAL</small></div></div></div><div class="arrival-welcome-copy"><span class="arrival-welcome-eyebrow">YOUR PERSONAL STUDY SPACE</span><h1 id="arrival-welcome-title">${isNew?"Welcome to StudyTrack":"Welcome back"}, ${escapeHtml(name)}!</h1><p>Your next chapter starts now. Let’s make today count.</p></div><div class="arrival-progress-track"><i></i></div><span class="arrival-welcome-footnote">A little progress, every day.</span></div>`;
  document.body.append(overlay);requestAnimationFrame(()=>{overlay.classList.add("visible");overlay.querySelector(".arrival-skip")?.focus({preventScroll:true});});
  arrivalWelcomeTimer=setTimeout(dismissArrivalWelcome,3000);
}

function dismissArrivalWelcome(){
  if(arrivalWelcomeTimer){clearTimeout(arrivalWelcomeTimer);arrivalWelcomeTimer=null;}
  const overlay=document.querySelector(".arrival-welcome-screen");if(!overlay||overlay.classList.contains("closing"))return;
  overlay.classList.add("closing");setTimeout(()=>overlay.remove(),420);
}

function oauthMessage(code,provider=""){
  const providerName={google:"Google",github:"GitHub",telegram:"Telegram"}[provider];
  if(code==="not_configured"&&providerName){const key=provider.toUpperCase();return `${providerName} sign-in needs setup by the app owner. In Render → your StudyTrack service → Environment, add STUDYTRACK_${key}_CLIENT_ID and STUDYTRACK_${key}_CLIENT_SECRET (and set STUDYTRACK_PUBLIC_URL to this site's origin). Register this exact callback URL with ${providerName}: ${location.origin}/auth/${provider}/callback. Save and redeploy.`;}
  if(code==="failed"&&providerName)return `${providerName} could not finish sign-in. Check that its client ID and secret are correct in Render and that its registered callback exactly matches ${location.origin}/auth/${provider}/callback.`;
  return({not_configured:"This sign-in option is not set up yet. Ask the app owner to add its provider credentials and callback URL.",cancelled:"Sign-in was cancelled.",telegram_unlinked:"First sign in with email, Google, or GitHub, then connect Telegram under Settings & privacy.",login_required:"Sign in to StudyTrack before connecting another sign-in method.",link_conflict:"That provider account is already connected to a different StudyTrack account.",failed:"Social sign-in could not be completed. Check the provider callback URL and try again."})[code]||"";
}
async function boot(){
  const resetToken=new URLSearchParams(window.location.hash.slice(1)).get("password_reset");
  if(resetToken){window.history.replaceState(null,"",window.location.pathname+window.location.search);renderPasswordRecovery("reset",{token:resetToken});return;}
  migrateDarkThemeDefault("guest");syncTheme();applyAdminBackground("angkor");getAppSettings().then(appearance=>applyAdminBackground(appearance.background||"angkor")).catch(()=>{});
  const query=new URLSearchParams(location.search),authError=oauthMessage(query.get("auth_error"),query.get("provider")),linked=query.get("auth_status")==="linked";if(query.has("auth_error")||query.has("auth_status"))history.replaceState(null,"",location.pathname+location.hash);
  try{const session=await restoreSession();if(session.user){const data=await getRemoteData();replaceDataFromServer(data);migrateDarkThemeDefault(`account:${session.user.id}`);localStorage.setItem("studytrack_account_id",session.user.id);appShell.classList.remove("hidden");authRoot.classList.add("hidden");syncTheme();syncProfileChrome();setSyncStatus(true);navigate(linked?"settings":session.user.role==="admin"?"admin":"dashboard");if(getSettings().pinEnabled)renderLock();if(linked)notify("Sign-in method connected");}else renderAuthScreen("login","student",authError);}
  catch(error){renderAuthScreen("login","student",authError||error.message||"The StudyTrack account server is unavailable. Start it with py server.py and reopen http://127.0.0.1:8000.");}
}

function setSyncStatus(ok){const pill=document.getElementById("sync-pill"),label=document.getElementById("sync-label");if(!pill||!label)return;label.textContent=ok?"Account synced":"Sync paused";pill.classList.toggle("sync-error",!ok);}
window.addEventListener("studytrack:sync-status",event=>setSyncStatus(Boolean(event.detail?.ok)));

async function signOut(){if(!window.confirm("Sign out of this StudyTrack account on this device? Your saved account data will stay online."))return;try{await logout();clearAll();localStorage.removeItem("studytrack_account_id");window.location.reload();}catch(error){notify(error.message||"Could not sign out","error");}}

async function copyClassCode(code,button){const value=String(code||"").trim();if(!value)return notify("There is no class code to copy.","error");try{let copied=false;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);copied=true;}}catch{}if(!copied){const input=document.createElement("textarea");input.value=value;input.setAttribute("readonly","");input.style.position="fixed";input.style.opacity="0";document.body.append(input);input.select();copied=document.execCommand("copy");input.remove();}if(!copied)throw new Error("Clipboard access was blocked.");if(button){button.dataset.originalLabel=button.dataset.originalLabel||button.textContent.trim();button.innerHTML=`${iconMarkup("check")} Copied!`;button.classList.add("copy-complete");setTimeout(()=>{if(button.isConnected){button.textContent=button.dataset.originalLabel||"Copy";button.classList.remove("copy-complete");}},1800);}notify("Class join code copied");}catch(error){notify("Could not copy the class code. Select the code and copy it manually.","error");}}
function applyAdminBackground(value){const body=document.body;body.removeAttribute("data-admin-background");body.style.removeProperty("--studytrack-custom-background");if(value==="aurora"){body.dataset.adminBackground="aurora";return;}if(typeof value==="string"&&/^data:image\/(?:gif|png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value)){body.dataset.adminBackground="custom";body.style.setProperty("--studytrack-custom-background",`url("${value}")`);return;}body.dataset.adminBackground="angkor";}
async function saveAdminBackground(value){if(!["angkor","aurora"].includes(value))return;const previous=adminBackground;adminBackground=value;applyAdminBackground(value);try{await updateAdminSettings({background:value});notify(value==="aurora"?"Animated background applied for everyone":"Angkor Wat background restored for everyone");await loadAdminConsole();}catch(error){adminBackground=previous;applyAdminBackground(previous);notify(error.message||"Could not save the shared background","error");}}
async function saveCustomAdminBackground(file){const input=document.getElementById("admin-background-file");try{if(!["image/gif","image/png","image/jpeg","image/webp"].includes(file.type))throw new Error("Choose a GIF, PNG, JPG, or WebP image.");if(file.size>2*1024*1024)throw new Error("Choose a background image under 2 MB.");const background=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||""));reader.onerror=()=>reject(new Error("Could not read that image."));reader.readAsDataURL(file);});const previous=adminBackground;applyAdminBackground(background);await updateAdminSettings({background});adminBackground=background;notify("Custom background saved for everyone");await loadAdminConsole();}catch(error){applyAdminBackground(adminBackground);notify(error.message||"Could not save that background","error");}finally{if(input)input.value="";}}

async function saveProfilePhoto(file){if(file.size>8*1024*1024){notify("Choose an image smaller than 8 MB","error");return;}try{const data=await resizeProfileImage(file),profile=read("profile");write("profile",{...profile,photo:data});syncProfileChrome();const preview=document.getElementById("profile-photo-preview");if(preview){preview.classList.add("has-photo");preview.innerHTML=`<img src="${escapeHtml(data)}" alt="Profile picture">`;}notify("Profile picture saved to your account");}catch(error){notify("Could not load that image. Try a JPG, PNG, or WebP file.","error");}}
async function saveProfileCover(file){if(file.size>10*1024*1024){notify("Choose a cover image smaller than 10 MB","error");return;}try{const data=await resizeCoverImage(file),profile=read("profile");write("profile",{...profile,coverPhoto:data});navigate("settings");notify("Cover photo saved to your account");}catch(error){notify(error.message||"Could not load that cover image. Try a JPG, PNG, or WebP file.","error");}}
function resizeCoverImage(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext("2d");if(!ctx){URL.revokeObjectURL(url);reject(new Error("Canvas unavailable"));return;}ctx.fillStyle="#d9d4ff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);const data=canvas.toDataURL("image/jpeg",.72);if(data.length>600000){reject(new Error("This image is too detailed to save. Choose a smaller picture."));return;}resolve(data);};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("Invalid image"));};img.src=url;});}
function resizeProfileImage(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const max=320,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext("2d");if(!ctx){URL.revokeObjectURL(url);reject(new Error("Canvas unavailable"));return;}ctx.fillStyle="#ffffff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL("image/jpeg",.82));};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("Invalid image"));};img.src=url;});}
function removeProfilePhoto(){const profile=read("profile");profile.photo="";write("profile",profile);syncProfileChrome();navigate("settings");notify("Profile picture removed");}
function removeProfileCover(){const profile=read("profile");profile.coverPhoto="";write("profile",profile);navigate("settings");notify("Cover photo removed");}

async function openSharedProfile(profileId){if(!profileId)return;try{const{profile,shared_class_id}=await studentProfile(profileId);if(!profile)return;const photo=safePhoto(profile.photo),cover=safePhoto(profile.coverPhoto),initial=escapeHtml((profile.avatar||profile.name?.[0]||"S").slice(0,2).toUpperCase()),coverContent=cover?`<img src="${escapeHtml(cover)}" alt="">`:`<div class="profile-modal-cover-art" aria-hidden="true"><span>✦</span><i></i><i></i></div>`,imageMarkup=photo?`<img src="${escapeHtml(photo)}" alt="${escapeHtml(profile.name)}">`:initial,roleLabel=profile.role==="teacher"?"TEACHER":profile.role==="admin"?"ADMIN":"STUDENT",shareMessage=profile.visibility==="everyone"?"This profile is visible to StudyTrack accounts.":profile.visibility==="private"?"This member keeps their profile details private.":"Photos and About me are shared with classmates only.";modalRoot.innerHTML=`<div class="modal-backdrop profile-modal-backdrop" data-close-modal><section class="modal profile-view-modal" role="dialog" aria-modal="true" aria-label="${escapeHtml(profile.name)} profile"><button class="profile-modal-close" type="button" data-close-modal aria-label="Close profile">×</button><div class="profile-modal-cover">${coverContent}<span class="profile-cover-glow"></span></div><div class="profile-modal-content"><div class="profile-modal-avatar ${photo?"has-photo":""}">${imageMarkup}</div><div class="profile-modal-heading"><div><span class="role-tag ${profile.role}">${roleLabel}</span><h2>${escapeHtml(profile.name)}</h2><p>${roleLabel[0]+roleLabel.slice(1).toLowerCase()} account</p></div><button class="btn btn-primary btn-small" data-action="message-profile" data-id="${escapeHtml(profile.id)}" data-class-id="${escapeHtml(shared_class_id||"")}">✉ Message</button></div>${profile.private?`<div class="profile-private-note"><span>◉</span><div><b>Profile details aren’t visible here</b><small>${profile.visibility==="private"?"This member keeps their photos and About me private.":"Photos and About me are shared with classmates only, so they are hidden outside a shared class."}</small></div></div>`:`<section class="profile-bio-card"><span class="eyebrow">ABOUT ME</span><p>${profile.bio?escapeHtml(profile.bio):"This member has not added an introduction yet."}</p></section>`}<div class="profile-modal-footer"><span>${shareMessage}</span><span>✦ StudyTrack</span></div></div></section></div>`;}catch(error){notify(error.message||"Could not open that profile","error");}}


document.addEventListener("submit",async event=>{if(event.target.id==="unlock-form"){event.preventDefault();const settings=getSettings(),entered=document.getElementById("unlock-pin").value;if(await hashPin(entered)===settings.pinHash){document.getElementById("lock-screen").classList.add("hidden");document.getElementById("lock-screen").innerHTML="";}else{document.getElementById("lock-error").textContent="That PIN did not match. Try again.";document.getElementById("unlock-pin").value="";}return;}
  if(event.target.dataset.form==="pin-setup"){event.preventDefault();const data=new FormData(event.target),pin=String(data.get("pin")||""),confirmPin=String(data.get("confirm")||"");if(!/^\d{4,12}$/.test(pin))return notify("Use 4 to 12 digits for your PIN","error");if(pin!==confirmPin)return notify("The PINs do not match","error");const settings=getSettings();settings.pinEnabled=true;settings.pinHash=await hashPin(pin);saveSettings(settings);closeModal();notify("Local PIN lock enabled");refresh();}
});

